#include <set>
#include <string>
#include <iostream>

// SWO Violation: Comparing only by length, ignores content difference
struct BadComp {
    bool operator()(const std::string& a, const std::string& b) const {
        return a.length() < b.length();
    }
};

int main() {
    // std::set<std::string, BadComp> s; // DANGER: UB potential
    // s.insert("apple");
    // s.insert("banana"); // Lengths 5 and 6, OK
    // s.insert("grape");  // Length 5. Equivalent to "apple" by length.

    // If the internal logic assumes 'grape' is strictly ordered relative to 'apple', 
    // the structure is corrupted because they are equivalent by BadComp.

    std::set<int> s; // Uses std::less<int>, which satisfies SWO
    s.insert(5);
}
